  SchoolConfig_1_Name = {Text = "Kaos"},
  SchoolConfig_1_SchoolBattleTips_1 = {
    Text = "Gümüş Anahtar Rezonansı: Tur sonunda 250 Keyflare kazan. Posse serbest bırakıldıktan sonra, tüm Uyandırıcılar <BlueQuality:[Arg1]> Aliemus kazanır. İkinci Posse serbest bırakıldığında, bunun yerine \"Unutulmamış Şafak\" serbest bırakılır: Serbest bırakmak için kilidi açılmış bir Posse seç ve etkisini iki kez uygula; her kilidi açılmış Posse bu Keşifte yalnızca bir kez seçilebilir ve başlangıçta taşınan Posse seçilemez."
