  SchoolConfig_3_Tips = {
    Text = "Boyut Mekiği: Her turda ilk Komut Kartı oynandıktan sonra, onun Geçici Temel Kopyasını Ultra Uzayına taşır. Ultra Turlarda tetiklenemez.\n\n\n\n\nUltra Tur: Ultra Tura girildiğinde, çekme yerine Ultra Uzayındaki tüm kartlar ele yerleştirilir. Ultra Turlarda verilen Hasar, Kalkan, HP Yenilenmesi, Keyflare, Aliemus, Güç değişimleri, Zehir, Karşı Saldırı ve Kanama -%25 azalır.\nYok Oluş: Tur başına bir kez, Ultra Uzayındaki en soldaki kartı kaldırır ve 1 \"Kavrayış\" kazanır.\n\n\nUltra Ustalık: Her 1 Diyar Ustalığı puanı için, tur başında %0,125 olasılıkla 1 \"Kavrayış\" kazanılır. Olasılık %100'ü aşarsa, birden fazla kopya elde edilebilir.\n\n\nSaf Ultra: Takım yalnızca Ultra Uyandırıcılardan oluşuyorsa, Ultra Ustalık etkisi iki katına çıkar ve takım artık Ultra Turlardaki istatistik düşüşünden etkilenmez."
  },
  SchoolConfig_4_Name = {Text = "Aequor"},
